do $$ begin
 if exists(select 1 from public.catalogue_parallel_rules t join desired_catalogue_parallel_rules e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.parallel_group is distinct from e.parallel_group or t.applies_to is distinct from e.applies_to or t.parallel is distinct from e.parallel or t.serial_cap is distinct from e.serial_cap or t.serial_exact is distinct from e.serial_exact or t.exclusive_note is distinct from e.exclusive_note or t.numbering_note is distinct from e.numbering_note or t.verification_status is distinct from e.verification_status)
 then raise exception 'Conflicting catalogue_parallel_rules identity; refusing overwrite'; end if;
end $$;
insert into public.catalogue_parallel_rules(id,set_id,parallel_group,applies_to,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status) select id,set_id,parallel_group,applies_to,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status from desired_catalogue_parallel_rules on conflict do nothing;
create temporary table desired_catalogue_sources on commit drop as select * from jsonb_populate_recordset(null::public.catalogue_sources,'[{"id":"2024-topps-chrome-star-wars-checklist","set_id":"2024-topps-chrome-star-wars","source":"Topps","purpose":"Checklist","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/CheckList_24SWCM_VERSION5.pdf","notes":"Complete printed checklist independently reconciled; source differences and unnumbered entries documented in batch audit."},{"id":"2024-topps-chrome-star-wars-product","set_id":"2024-topps-chrome-star-wars","source":"Topps","purpose":"Product identity and release date","url":"https://www.topps.com/products/2024-topps-star-wars-chrome-hobby-box","notes":"Official title year retained with actual US availability; generic product metadata is not a separate set."},{"id":"2024-topps-chrome-star-wars-odds","set_id":"2024-topps-chrome-star-wars","source":"Topps","purpose":"Parallel applicability","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/2024StarWarsChromeOdds.pdf","notes":"Official odds rows retained; no inferred caps or grids."},{"id":"2024-topps-star-wars-chrome-sapphire-checklist","set_id":"2024-topps-star-wars-chrome-sapphire","source":"Topps","purpose":"Checklist","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/STW2476-2024StarWarsChromeSapphireChecklistV3.pdf","notes":"Complete printed checklist independently reconciled; source differences and unnumbered entries documented in batch audit."},{"id":"2024-topps-star-wars-chrome-sapphire-product","set_id":"2024-topps-star-wars-chrome-sapphire","source":"Topps","purpose":"Product identity and release date","url":"https://www.topps.com/products/2024-topps-star-wars-chrome-sapphire-edition-sealed-case","notes":"Official title year retained with actual US availability; generic product metadata is not a separate set."},{"id":"2024-topps-star-wars-chrome-sapphire-odds","set_id":"2024-topps-star-wars-chrome-sapphire","source":"Topps","purpose":"Parallel applicability","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/2024StarWarsChromeSapphireOdds.pdf","notes":"Official odds rows retained; no inferred caps or grids."},{"id":"2022-topps-star-wars-masterwork-checklist","set_id":"2022-topps-star-wars-masterwork","source":"Topps","purpose":"Checklist","url":"https://cdn.shopify.com/s/files/1/0662/9749/5709/files/STW2256-CheckList_2022StarWarsMasterwork.pdf","notes":"Complete printed checklist independently reconciled; source differences and unnumbered entries documented in batch audit."},{"id":"2022-topps-star-wars-masterwork-product","set_id":"2022-topps-star-wars-masterwork","source":"Topps","purpose":"Product identity and release date","url":"https://www.topps.com/products/2022-star-wars-masterwork-master-box","notes":"Official title year retained with actual US availability; generic product metadata is not a separate set."},{"id":"2022-topps-star-wars-masterwork-odds","set_id":"2022-topps-star-wars-masterwork","source":"Topps","purpose":"Unrecovered odds source","url":"https://www.topps.com/media/pdf/odds/StarWarsMasterWorkOdds.pdf","notes":"Manufacturer-linked document returns 404; no pack rates or parallel cap rules imported for Masterwork. Checklist identities are verified separately."}]'::jsonb);
do $$ begin
 if exists(select 1 from public.catalogue_sources t join desired_catalogue_sources e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.source is distinct from e.source or t.purpose is distinct from e.purpose or t.url is distinct from e.url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_sources identity; refusing overwrite'; end if;
end $$;
insert into public.catalogue_sources(id,set_id,source,purpose,url,notes) select id,set_id,source,purpose,url,notes from desired_catalogue_sources on conflict do nothing;
do $$ begin
 if (select count(*) from public.catalogue_sets where id='2024-topps-chrome-star-wars')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2024-topps-chrome-star-wars')<>16
 or (select count(*) from public.catalogue_cards where set_id='2024-topps-chrome-star-wars')<>838
 or (select count(*) from public.catalogue_variants where set_id='2024-topps-chrome-star-wars')<>838
 or (select count(*) from public.catalogue_parallel_rules where set_id='2024-topps-chrome-star-wars')<>71
 or (select count(*) from public.catalogue_sources where set_id='2024-topps-chrome-star-wars')<>3
 or (select count(*) from public.catalogue_sets where id='2024-topps-star-wars-chrome-sapphire')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2024-topps-star-wars-chrome-sapphire')<>8
 or (select count(*) from public.catalogue_cards where set_id='2024-topps-star-wars-chrome-sapphire')<>187
 or (select count(*) from public.catalogue_variants where set_id='2024-topps-star-wars-chrome-sapphire')<>187
 or (select count(*) from public.catalogue_parallel_rules where set_id='2024-topps-star-wars-chrome-sapphire')<>41
 or (select count(*) from public.catalogue_sources where set_id='2024-topps-star-wars-chrome-sapphire')<>3
 or (select count(*) from public.catalogue_sets where id='2022-topps-star-wars-masterwork')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2022-topps-star-wars-masterwork')<>20
 or (select count(*) from public.catalogue_cards where set_id='2022-topps-star-wars-masterwork')<>372
 or (select count(*) from public.catalogue_variants where set_id='2022-topps-star-wars-masterwork')<>372
 or (select count(*) from public.catalogue_parallel_rules where set_id='2022-topps-star-wars-masterwork')<>0
 or (select count(*) from public.catalogue_sources where set_id='2022-topps-star-wars-masterwork')<>3
 or (select count(*) from public.catalogue_sets)<>42
 or (select count(*) from public.catalogue_cards)<>20616
 or exists(select 1 from public.catalogue_variants v left join public.catalogue_cards c on c.id=v.card_id where v.set_id in ('2024-topps-chrome-star-wars','2024-topps-star-wars-chrome-sapphire','2022-topps-star-wars-masterwork') and (c.id is null or c.set_id<>v.set_id))
 or exists(select 1 from public.catalogue_subsets s where s.set_id in ('2024-topps-chrome-star-wars','2024-topps-star-wars-chrome-sapphire','2022-topps-star-wars-masterwork') and s.card_count<>(select count(*) from public.catalogue_cards c where c.set_id=s.set_id and c.subset_code=s.subset_code))
 or exists(select row from before_catalogue_sets except all select to_jsonb(t) from public.catalogue_sets t)
 or exists(select row from before_catalogue_subsets except all select to_jsonb(t) from public.catalogue_subsets t)
 or exists(select row from before_catalogue_cards except all select to_jsonb(t) from public.catalogue_cards t)
 or exists(select row from before_catalogue_variants except all select to_jsonb(t) from public.catalogue_variants t)
 or exists(select row from before_catalogue_parallel_rules except all select to_jsonb(t) from public.catalogue_parallel_rules t)
 or exists(select row from before_catalogue_sources except all select to_jsonb(t) from public.catalogue_sources t)
 or exists(select row from before_collection_items except all select to_jsonb(t) from public.collection_items t)
 or exists(select row from before_reference_images except all select to_jsonb(t) from public.reference_images t)
 or exists(select to_jsonb(t) from public.collection_items t except all select row from before_collection_items)
 or exists(select to_jsonb(t) from public.reference_images t except all select row from before_reference_images)
 then raise exception 'Count, linkage or preservation check failed'; end if;
end $$;
select 'verified' as result,(select count(*) from public.catalogue_cards) as cards,(select count(*) from public.collection_items) as collections;
commit;
